using System.Globalization;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using OpenSecurityPlatform.Foundation;
namespace OpenSecurityPlatform.Infrastructure;
public sealed class OpenSearchExecutionProjection : IExecutionProjection { public const string Alias = "platform-execution-events"; static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); readonly HttpClient _client; public OpenSearchExecutionProjection(HttpClient client, string url, string? user, string? password) { client.BaseAddress = new(url); client.Timeout = TimeSpan.FromSeconds(15); if (!string.IsNullOrWhiteSpace(user)) client.DefaultRequestHeaders.Authorization = new("Basic", Convert.ToBase64String(Encoding.UTF8.GetBytes($"{user}:{password}"))); _client = client; } public async Task EnsureAsync(CancellationToken ct) { using var found = await _client.GetAsync($"_alias/{Alias}", ct); if (!found.IsSuccessStatusCode) { var index = $"{Alias}-v1"; using (var create = await _client.PutAsJsonAsync(index, Definition(), ct)) create.EnsureSuccessStatusCode(); using var alias = await _client.PostAsJsonAsync("_aliases", new { actions = new[] { new { add = new { index, alias = Alias } } } }, ct); alias.EnsureSuccessStatusCode(); } using var mapping = await _client.PutAsJsonAsync($"{Alias}/_mapping", Mapping(), ct); mapping.EnsureSuccessStatusCode(); } public async Task UpsertAsync(string tenant, ExecutionObservation v, CancellationToken ct) { using var response = await _client.PutAsJsonAsync($"{Alias}/_doc/{tenant}-{v.EventId}", Doc(tenant, v), ct); response.EnsureSuccessStatusCode(); } public async Task<ExecutionEventPage> SearchAsync(string tenant, ExecutionSearchRequest r, CancellationToken ct) { var f = new List<object> { new { term = new { tenant_id = tenant } } }; if (r.EndpointId is { } endpoint) f.Add(new { term = new { endpoint_id = endpoint } }); if (r.SourcePid is { } spid) f.Add(new { term = new { source_pid = spid } }); if (r.TargetPid is { } tpid) f.Add(new { term = new { target_pid = tpid } }); if (r.Operation is { } operation) f.Add(new { term = new { operation } }); if (r.HandleType is { } handle) f.Add(new { term = new { handle_type = handle } }); if (r.AccessFlag is { } access) f.Add(new { term = new { access_flags = access } }); if (r.MemoryProtection is { } protection) f.Add(new { term = new { memory_protection = protection } }); if (r.ExecutableMemory is { } executable) f.Add(new { term = new { executable_memory = executable } }); if (r.ThreadId is { } tid) f.Add(new { term = new { thread_id = tid } }); if (r.StartAddress is { } start) f.Add(new { term = new { start_address = start.ToString(CultureInfo.InvariantCulture) } }); if (r.SectionIdentity is { } section) f.Add(new { term = new { section_entity_id = section } }); if (r.Kind is { } kind) f.Add(new { term = new { event_type = kind.ToString() } }); if (r.From is not null || r.To is not null) f.Add(new { range = new { observed_at = new { gte = r.From, lte = r.To } } }); var terms = new[] { r.SourceProcess, r.TargetProcess }.Where(x => !string.IsNullOrWhiteSpace(x)).Select(x => (object)new { simple_query_string = new { query = Escape(x), fields = new[] { "source_process", "target_process", "source_image", "target_image" } } }).ToArray(); var body = new Dictionary<string, object?> { { "size", Math.Clamp(r.PageSize, 1, 500) }, { "query", new { @bool = new { filter = f, must = terms } } }, { "sort", new object[] { new { observed_at = new { order = "desc" } }, new { event_id = new { order = "desc" } } } } }; if (!string.IsNullOrWhiteSpace(r.Cursor)) body["search_after"] = JsonSerializer.Deserialize<object[]>(TenantCursor.Unprotect(tenant, r.Cursor)); using var response = await _client.PostAsJsonAsync($"{Alias}/_search", body, ct); response.EnsureSuccessStatusCode(); using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct)); var list = new List<ExecutionObservation>(); string? cursor = null; foreach (var hit in doc.RootElement.GetProperty("hits").GetProperty("hits").EnumerateArray()) { list.Add(JsonSerializer.Deserialize<ExecutionObservation>(hit.GetProperty("_source").GetProperty("event_data").GetRawText(), Json)!); cursor = TenantCursor.Protect(tenant, hit.GetProperty("sort").GetRawText()); } return new(list, cursor); } public async Task<bool> HealthAsync(CancellationToken ct) { try { using var r = await _client.GetAsync("_cluster/health", ct); return r.IsSuccessStatusCode; } catch (HttpRequestException) { return false; } } static object Doc(string tenant, ExecutionObservation v) => new { tenant_id = tenant, endpoint_id = v.EndpointId, event_id = v.EventId, event_type = v.Kind.ToString(), entity_id = v.Thread?.ThreadEntityId ?? v.Memory?.RegionEntityId ?? v.Section?.SectionEntityId ?? v.TargetProcess?.ProcessEntityId ?? v.SourceProcess?.ProcessEntityId, source_process = v.SourceProcess?.ProcessEntityId, target_process = v.TargetProcess?.ProcessEntityId, source_image = v.SourceProcess?.ImagePath, target_image = v.TargetProcess?.ImagePath, source_pid = v.SourceProcess?.ProcessId, target_pid = v.TargetProcess?.ProcessId, operation = v.Native.NativeOperation, handle_type = v.Handle?.HandleType, access_mask = v.Handle?.DesiredAccess, access_flags = v.Handle?.DesiredAccessFlags, memory_protection = v.Memory?.ProtectionAfter ?? v.Memory?.ProtectionBefore, executable_memory = v.Memory?.Executable, thread_id = v.Thread?.ThreadId, start_address = v.Thread?.StartAddress?.ToString(CultureInfo.InvariantCulture), section_entity_id = v.Section?.SectionEntityId, data_quality = v.DataQualityFlags, observed_at = v.ObservedAt, event_data = v }; static Dictionary<string, object> Properties() => new() { { "tenant_id", new { type = "keyword" } }, { "endpoint_id", new { type = "keyword" } }, { "event_id", new { type = "keyword" } }, { "event_type", new { type = "keyword" } }, { "entity_id", new { type = "keyword" } }, { "source_process", new { type = "keyword" } }, { "target_process", new { type = "keyword" } }, { "source_image", new { type = "wildcard" } }, { "target_image", new { type = "wildcard" } }, { "source_pid", new { type = "integer" } }, { "target_pid", new { type = "integer" } }, { "operation", new { type = "keyword" } }, { "handle_type", new { type = "keyword" } }, { "access_mask", new { type = "long" } }, { "access_flags", new { type = "keyword" } }, { "memory_protection", new { type = "long" } }, { "executable_memory", new { type = "boolean" } }, { "thread_id", new { type = "integer" } }, { "start_address", new { type = "keyword" } }, { "section_entity_id", new { type = "keyword" } }, { "data_quality", new { type = "keyword" } }, { "observed_at", new { type = "date" } }, { "event_data", new { type = "object", enabled = false } } }; static object Mapping() => new { properties = Properties() }; static object Definition() => new { settings = new { index = new { number_of_shards = 1, number_of_replicas = 0 } }, mappings = new { dynamic = "strict", properties = Properties() } }; static string Escape(string? value) => string.Concat((value ?? "").Take(256).Select(c => char.IsLetterOrDigit(c) || char.IsWhiteSpace(c) || c is '.' or '_' or '-' or '/' or '\\' or ':' ? c : ' ')); }
